-- VisualForge AI — Phase 1 schema. RLS: clients NEVER read differences of unfinished levels.
create table if not exists images (id uuid primary key default gen_random_uuid(), owner_id uuid, storage_path text not null, width int not null, height int not null, source text not null check (source in ('upload','generated','mock')), expires_at timestamptz default now()+interval '24 hours', created_at timestamptz default now());
create table if not exists generation_jobs (id uuid primary key default gen_random_uuid(), image_id uuid references images(id), mode text not null check (mode in ('game','qc')), status text not null default 'queued', stage text, requested_changes int not null default 7, is_mock boolean not null default false, error text, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists levels (id uuid primary key default gen_random_uuid(), job_id uuid references generation_jobs(id), original_image_id uuid references images(id), modified_image_id uuid references images(id), mode text not null, is_mock boolean not null default false, published boolean not null default false, created_at timestamptz default now());
-- differences: NO public select policy until level published AND (game finished by requester) — enforced in API too.
create table if not exists differences (id uuid primary key default gen_random_uuid(), level_id uuid references levels(id) on delete cascade, type text not null, description text not null, bbox jsonb not null, bbox_normalized jsonb not null, mask_url text, severity text default 'medium', verification_status text default 'needs_review', verifier_notes text default '');
create table if not exists game_sessions (id uuid primary key default gen_random_uuid(), level_id uuid references levels(id), player_id uuid, found_ids uuid[] default '{}', mistakes int default 0, hints_used int default 0, score int default 0, finished boolean default false, started_at timestamptz default now(), finished_at timestamptz);
create table if not exists rooms (id uuid primary key default gen_random_uuid(), code text unique not null, host_id uuid, status text default 'lobby', round_number int default 1, expires_at timestamptz default now()+interval '2 hours', created_at timestamptz default now());
create table if not exists room_players (id uuid primary key default gen_random_uuid(), room_id uuid references rooms(id) on delete cascade, player_id uuid, display_name text not null, color text not null, ready boolean default false, score int default 0, unique(room_id, player_id));
create table if not exists rounds (id uuid primary key default gen_random_uuid(), room_id uuid references rooms(id) on delete cascade, level_id uuid references levels(id), round_number int not null, status text default 'pending', starts_at timestamptz, ends_at timestamptz);
-- RACE GUARD: first valid find wins, enforced by the DB itself.
create table if not exists round_finds (id uuid primary key default gen_random_uuid(), round_id uuid references rounds(id) on delete cascade, difference_id uuid references differences(id), player_id uuid not null, found_at timestamptz default now(), unique(round_id, difference_id));
create table if not exists qc_sessions (id uuid primary key default gen_random_uuid(), trainee_id uuid, level_id uuid references levels(id), correct int default 0, missed int default 0, false_positives int default 0, accuracy numeric, duration_sec int, created_at timestamptz default now());
create table if not exists qc_responses (id uuid primary key default gen_random_uuid(), session_id uuid references qc_sessions(id) on delete cascade, click jsonb not null, was_correct boolean not null, difference_id uuid);
create table if not exists datasets (id uuid primary key default gen_random_uuid(), name text not null, note text default 'synthetic — validate before industrial use', created_at timestamptz default now());
create table if not exists dataset_samples (id uuid primary key default gen_random_uuid(), dataset_id uuid references datasets(id) on delete cascade, level_id uuid references levels(id), approved boolean, verified boolean not null default false);
create table if not exists ai_calls (id uuid primary key default gen_random_uuid(), job_id uuid, model text not null, operation text not null, latency_ms int, estimated_cost_usd numeric, is_mock boolean not null default false, created_at timestamptz default now());
alter table images enable row level security;
alter table differences enable row level security;
alter table levels enable row level security;
-- Deliberately restrictive default: no anon select on differences (server role only, validated click API).
create policy "levels public read if published" on levels for select using (published = true);
create policy "images public read" on images for select using (true);
insert into storage.buckets (id, name, public) values ('originals','originals',true),('generated','generated',true),('masks','masks',true) on conflict (id) do nothing;
